import customers from './customers.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'customer_lookup',
      description: 'Look up a customer by their customer_id and return their details.',
      inputSchema: {
        type: 'object',
        properties: {
          customer_id: {
            type: 'string',
            description: 'The unique identifier of the customer to look up.',
          },
        },
        required: ['customer_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (
    typeof args !== 'object' ||
    args === null ||
    Array.isArray(args)
  ) {
    throw new Error('Invalid arguments: expected an object');
  }

  const { customer_id, ...rest } = args;

  if (customer_id === undefined || customer_id === null) {
    throw new Error("Missing required argument: customer_id");
  }
  if (typeof customer_id !== 'string') {
    throw new Error('Invalid argument: customer_id must be a string');
  }
  if (customer_id.trim() === '') {
    throw new Error('Invalid argument: customer_id must not be empty');
  }
  if (Object.keys(rest).length > 0) {
    throw new Error('Invalid arguments: unexpected properties provided');
  }

  const customer = customers[customer_id];
  if (!customer) {
    throw new Error(`Unknown customer: ${customer_id}`);
  }

  const text = `Customer ${customer_id}: ${customer.name} (tier: ${customer.tier})`;
  return { content: [{ type: 'text', text }] };
}

